mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM public.tb_drafting_work_category
    WHERE tenant_id = #{tenantId}
      AND drafting_work_category_id = #{draftingWorkCategoryId}
      AND use_at = 'Y'
      AND COALESCE(delete_status, 'N') <> 'Y'
)

INSERT INTO public.tb_electronic_approval_main (
    tenant_id, drafting_work_category_id, document_type, eabus_no, document_status, title,
    contents_json, contents_html, contents_text, drafter_id, drafter_name,
    drafter_department_name, created_at, updated_at, updated_by
) VALUES (
    #{tenantId}, #{draftingWorkCategoryId, jdbcType=BIGINT}, #{documentType}, #{eabusNo}, 'DRAFT', #{title},
    CAST(#{contentsJson} AS jsonb), #{contentsHtml}, #{contentsText}, #{drafterId},
    #{drafterName}, #{drafterDepartmentName}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, #{drafterId}
)
RETURNING electronic_approval_id

SELECT electronic_approval_id, document_type, document_status, drafter_id
FROM public.tb_electronic_approval_main
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND deleted_yn = 'N'
FOR UPDATE

mapper.update:
UPDATE public.tb_electronic_approval_main
SET document_status = #{nextDocumentStatus},
    submitted_at = COALESCE(submitted_at, CURRENT_TIMESTAMP),
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND document_status = #{expectedDocumentStatus}
  AND deleted_yn = 'N'

UPDATE public.tb_electronic_approval_main
SET document_status = 'DRAFT',
    submitted_at = NULL,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND drafter_id = #{drafterId}
  AND document_status = 'PENDING'
  AND deleted_yn = 'N'

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM public.tb_electronic_approval_line_info
    WHERE tenant_id = #{tenantId}
      AND electronic_approval_id = #{electronicApprovalId}
      AND stage_order > #{stageOrder}
      AND participant_type IN ('APPROVAL', 'AGREEMENT')
      AND action_status IN ('APPROVED', 'REJECTED', 'RETURNED')
)

mapper.update:
UPDATE public.tb_electronic_approval_line_info
SET action_status = 'PENDING',
    pending_at = CURRENT_TIMESTAMP,
    action_at = NULL,
    action_comment = NULL
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND electronic_approval_line_id = #{electronicApprovalLineId}
  AND participant_user_id = #{participantUserId}
  AND participant_type IN ('APPROVAL', 'AGREEMENT')
  AND action_status = 'APPROVED'

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM public.tb_electronic_approval_line_info drafter_line
    WHERE drafter_line.tenant_id = #{tenantId}
      AND drafter_line.electronic_approval_id = #{electronicApprovalId}
      AND drafter_line.stage_order = 1
      AND drafter_line.participant_type = 'APPROVAL'
      AND drafter_line.participant_user_id = #{participantUserId}
      AND drafter_line.action_status = 'APPROVED'
      AND drafter_line.action_at IS NOT NULL
)
AND NOT EXISTS (
    SELECT 1
    FROM public.tb_electronic_approval_line_info line
    WHERE line.tenant_id = #{tenantId}
      AND line.electronic_approval_id = #{electronicApprovalId}
      AND line.participant_type IN ('APPROVAL', 'AGREEMENT')
      AND NOT (
          line.stage_order = 1
          AND line.participant_type = 'APPROVAL'
          AND line.participant_user_id = #{participantUserId}
      )
      AND (
          line.action_status NOT IN ('WAITING', 'PENDING')
          OR line.action_at IS NOT NULL
          OR line.action_comment IS NOT NULL
      )
)

mapper.update:
UPDATE public.tb_electronic_approval_main
SET deleted_yn = 'Y',
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND drafter_id = #{drafterId}
  AND document_status IN ('DRAFT', 'PENDING')
  AND deleted_yn = 'N'

