UPDATE public.tb_electronic_approval_line_info
SET action_status = 'PENDING',
    pending_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND stage_order = #{stageOrder}
  AND participant_type IN ('APPROVAL', 'AGREEMENT')
  AND action_status = 'WAITING'

mapper.select:
SELECT m.electronic_approval_id, m.eabus_no, m.document_type, m.document_status,
       m.title, m.drafter_name, m.created_at, m.updated_at, m.submitted_at,
       LEFT(COALESCE(m.contents_text, ''), 240) AS summary,
       NULL::varchar AS notice_type
FROM public.tb_electronic_approval_main m
WHERE m.tenant_id = #{tenantId}
  AND m.deleted_yn = 'N'
  AND (
      m.drafter_id = #{drafterId}
      OR EXISTS (
          SELECT 1
          FROM public.tb_electronic_approval_line_info l
          WHERE l.tenant_id = m.tenant_id
            AND l.electronic_approval_id = m.electronic_approval_id
            AND l.participant_user_id = #{participantUserId}
      )
  )

    AND m.document_type = #{documentType}


    AND m.electronic_approval_id = #{electronicApprovalId}


    AND EXISTS (
        SELECT 1
        FROM public.tb_electronic_approval_line_info l
        WHERE l.tenant_id = m.tenant_id
          AND l.electronic_approval_id = m.electronic_approval_id
          AND l.participant_user_id = #{participantUserId}
          AND l.action_status = 'PENDING'
    )


    AND m.document_status IN ('PENDING', 'IN_PROGRESS')


    AND m.drafter_id = #{drafterId}
    AND m.document_status = 'DRAFT'


    AND m.document_status = #{scope}

ORDER BY m.updated_at DESC, m.electronic_approval_id DESC

SELECT m.electronic_approval_id, m.drafting_work_category_id,
       m.eabus_no, m.document_type, m.document_status,
       m.drafter_name, m.created_at, m.submitted_at, m.title,
       m.contents_json::text AS contents_json, m.contents_html, m.contents_text,
       m.view_count,
       (m.drafter_id = #{drafterId}) AS is_drafter
FROM public.tb_electronic_approval_main m
WHERE m.tenant_id = #{tenantId}
  AND m.electronic_approval_id = #{electronicApprovalId}
  AND m.deleted_yn = 'N'
  AND (
      m.drafter_id = #{drafterId}
      OR EXISTS (
          SELECT 1
          FROM public.tb_electronic_approval_line_info l
          WHERE l.tenant_id = m.tenant_id
            AND l.electronic_approval_id = m.electronic_approval_id
            AND l.participant_user_id = #{participantUserId}
      )
  )

SELECT m.electronic_approval_id, m.drafting_work_category_id, m.eabus_no, m.document_type, m.document_status, m.drafter_name, m.created_at, m.submitted_at, m.title, m.contents_json::text AS contents_json, m.contents_html, m.contents_text, m.view_count, (m.drafter_id = #{drafterId}) AS is_drafter FROM public.tb_electronic_approval_main m WHERE m.tenant_id = #{tenantId} AND m.electronic_approval_id IN
#{ownerId}
AND m.deleted_yn = 'N' AND ( m.drafter_id = #{drafterId} OR EXISTS ( SELECT 1 FROM public.tb_electronic_approval_line_info l WHERE l.tenant_id = m.tenant_id AND l.electronic_approval_id = m.electronic_approval_id AND l.participant_user_id = #{participantUserId} ) )

SELECT login_id
FROM public.tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}
  AND use_at = 'Y'

mapper.update:
UPDATE public.tb_electronic_approval_main
SET view_count = view_count + 1
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND deleted_yn = 'N'

mapper.select:
SELECT line.electronic_approval_id, line.electronic_approval_line_id, line.stage_order, line.participant_order, line.participant_type, line.participant_user_id, line.participant_name, line.participant_department_name, la.profile_image AS participant_profile_image, CASE WHEN line.participant_type = 'APPROVAL' AND line.action_status IN ('APPROVED', 'REJECTED', 'RETURNED') THEN la.stamp_image ELSE NULL END AS participant_stamp_image, line.action_status, line.pending_at, line.action_at, line.action_comment FROM public.tb_electronic_approval_line_info line LEFT JOIN public.tb_user u ON u.tenant_id = line.tenant_id AND CAST(u.user_id AS varchar) = line.participant_user_id LEFT JOIN public.tb_login_account la ON la.tenant_id = u.tenant_id AND la.login_id = u.login_id WHERE line.tenant_id = #{tenantId} AND line.electronic_approval_id IN
#{ownerId}
ORDER BY line.electronic_approval_id, line.stage_order, line.participant_order

SELECT EXISTS (
    SELECT 1
    FROM public.tb_electronic_approval_main m
    WHERE m.tenant_id = #{tenantId}
      AND m.electronic_approval_id = #{electronicApprovalId}
      AND m.deleted_yn = 'N'
      AND (
          m.drafter_id = #{drafterId}
          OR EXISTS (
              SELECT 1
              FROM public.tb_electronic_approval_line_info l
              WHERE l.tenant_id = m.tenant_id
                AND l.electronic_approval_id = m.electronic_approval_id
                AND l.participant_user_id = #{participantUserId}
          )
      )
)

SELECT drafter_id
FROM public.tb_electronic_approval_main
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND document_status IN ('DRAFT', 'REVISION_REQUESTED')
  AND deleted_yn = 'N'

SELECT electronic_approval_id, eabus_no, document_status, submitted_at
FROM public.tb_electronic_approval_main
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND drafter_id = #{drafterId}
  AND deleted_yn = 'N'
